-- OMS-001: AI source preparation, NOT clinical approval. Review before owner execution.
-- Source: content/drafts/OMS-001.review.json; original content and all publication guards retained.
BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE public.lessons, public.questions, public.answer_options, public.clinical_cases IN SHARE MODE;
LOCK TABLE public.content_curriculum_evidence IN SHARE ROW EXCLUSIVE MODE;
DO $preparation$
DECLARE r jsonb; s jsonb; fp text; v integer; old public.content_curriculum_evidence;
BEGIN
  IF (SELECT count(*) FROM pg_trigger WHERE tgname='guard_clinical_publication' AND tgenabled IN ('O','A')
      AND tgrelid IN ('public.lessons'::regclass,'public.questions'::regclass,'public.clinical_cases'::regclass)
      AND tgfoid='public.guard_clinical_publication()'::regprocedure) <> 3 THEN
    RAISE EXCEPTION 'All three publication guards must remain enabled';
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"id":"0a50c001-1124-4000-8000-000000000001","kind":"lesson","entity_id":"cd7a294f-a0ae-48bb-8fc0-be2ba24afdbe","fingerprint":"2ae20e042d5a77303de393a4373d2e0915e9e84e69b0224c1700665b86986c45","expected_version":0,"subject_slug":"oral-maxillofacial-surgery","evidence":{"unit":"OMS-001 — source preparation only","topic":"Safe Exodontia Assessment","outcomes":["Identify the history and clinical-context information missing from an extraction assessment.","Distinguish a source''s intended setting and medicine class before interpreting its pathway.","Explain why a generic bleeding scenario cannot establish a severity-specific answer.","Locate the exact evidence and unresolved gaps for a qualified educator to review."],"sources":[{"citation":"Indian Dental Association: For Patient Management","edition":"Undated accreditation webpage","section":"Standards 9, 10 and 12","url":"https://www.ida.org.in/Accreditation/Details/ForPatientManagement","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 3: Assessing Bleeding Risk — Clinical practice advice","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/assessing-bleeding-risk/clinical-practice-advice/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Introduction: About this guidance","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/introduction/about-this-guidance/","checked_on":"2026-11-24"}],"note":"AI-assisted source preparation, NOT independent clinical approval. Existing draft unchanged. The current lesson is a short generic introduction with no source references and objectives that cannot establish complete exodontia assessment coverage. Do not treat the proposed disease-specific checks or technical procedures in candidate v0.2 as source-complete. Prepare observable bounded outcomes and obtain topic-specific references and independent review before any teaching release. Candidate v0.2 requires further revision. Source metadata does not certify clinical truth, MCQ validity or Indian applicability."}},{"id":"0a50c001-1124-4000-8000-000000000002","kind":"question","entity_id":"6fac07ab-bc4a-463c-8d9d-7e262b9165b1","fingerprint":"1065c3a5654109132e9429db17acf7ed223311ef1597e391fe5f0a2ede03622b","expected_version":0,"subject_slug":"oral-maxillofacial-surgery","evidence":{"unit":"OMS-001 — source preparation only","topic":"Before an extraction, what must be verified?","outcomes":["Identify the history and clinical-context information missing from an extraction assessment.","Distinguish a source''s intended setting and medicine class before interpreting its pathway.","Explain why a generic bleeding scenario cannot establish a severity-specific answer.","Locate the exact evidence and unresolved gaps for a qualified educator to review."],"sources":[{"citation":"Indian Dental Association: For Patient Management","edition":"Undated accreditation webpage","section":"Standards 9, 10 and 12","url":"https://www.ida.org.in/Accreditation/Details/ForPatientManagement","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 3: Assessing Bleeding Risk — Clinical practice advice","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/assessing-bleeding-risk/clinical-practice-advice/","checked_on":"2026-11-24"}],"note":"AI-assisted source preparation, NOT independent clinical approval. Existing draft unchanged. The marked option omits medical/drug/allergy assessment while the explanation adds medical review; the broad stem implies a complete checklist. Distractors are conspicuously weak and do not establish clinical discrimination. Replace with a bounded scenario and have every option, rationale and ambiguity independently evaluated. Candidate v0.2 requires further revision. Source metadata does not certify clinical truth, MCQ validity or Indian applicability."}},{"id":"0a50c001-1124-4000-8000-000000000003","kind":"question","entity_id":"dc25b46f-5eea-419c-a51b-53009d7cfd17","fingerprint":"78a221f0f1bf841860e13a5556a4a18711484b47da395089955388b7521279ff","expected_version":0,"subject_slug":"oral-maxillofacial-surgery","evidence":{"unit":"OMS-001 — source preparation only","topic":"A patient reports persistent bleeding after extraction. What is the most appropriate first priority?","outcomes":["Identify the history and clinical-context information missing from an extraction assessment.","Distinguish a source''s intended setting and medicine class before interpreting its pathway.","Explain why a generic bleeding scenario cannot establish a severity-specific answer.","Locate the exact evidence and unresolved gaps for a qualified educator to review."],"sources":[{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Acute Dental Problems","edition":"Second edition (March 2026)","section":"Common oral conditions: Post-extraction haemorrhage — initial management and subsequent care","url":"https://www.acutedentalproblems.sdcep.org.uk/guidance/management-of-oral-conditions/common-oral-conditions/post-extraction-haemorrhage/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Acute Dental Problems","edition":"Second edition (March 2026); supporting practice guide added September 2026","section":"Prioritising dental emergencies — accessible version, decision point 4","url":"https://www.acutedentalproblems.sdcep.org.uk/supporting-tools/dental-practice-guide/prioritising-dental-emergencies/accessible-version/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 5: Direct oral anticoagulants — Recommendations; Monitoring","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/treatment-recommendations/direct-oral-anticoagulants-doacs/recommendations/","checked_on":"2026-11-24"}],"note":"AI-assisted source preparation, NOT independent clinical approval. Existing draft unchanged. The stem does not specify bleeding severity, timing, systemic state or medication; the current key cannot establish a complete severity-specific pathway. Distractors such as ignoring bleeding or another extraction are weak; a structural single answer is not clinical validity. Bound the setting and severity, source the escalation reasoning and review each option before release. Candidate v0.2 requires further revision. Source metadata does not certify clinical truth, MCQ validity or Indian applicability."}},{"id":"0a50c001-1124-4000-8000-000000000004","kind":"case","entity_id":"9ca96a5b-6cc9-43e1-b7fe-9346dcf101e2","fingerprint":"2919a43438e557a019ececb3b549bcd856f16955fc75027bc3ae6c171373e243","expected_version":0,"subject_slug":"oral-maxillofacial-surgery","evidence":{"unit":"OMS-001 — source preparation only","topic":"Safe Exodontia Assessment — Clinical Scenario","outcomes":["Identify the history and clinical-context information missing from an extraction assessment.","Distinguish a source''s intended setting and medicine class before interpreting its pathway.","Explain why a generic bleeding scenario cannot establish a severity-specific answer.","Locate the exact evidence and unresolved gaps for a qualified educator to review."],"sources":[{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 3: Assessing Bleeding Risk — Clinical practice advice","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/assessing-bleeding-risk/clinical-practice-advice/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 6: Warfarin or another Vitamin K antagonist — recommendation and clinical practice advice","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/treatment-recommendations/warfarin-or-another-vitamin-k-antagonist/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Section 5: Direct oral anticoagulants — Recommendations; Monitoring","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/treatment-recommendations/direct-oral-anticoagulants-doacs/recommendations/","checked_on":"2026-11-24"},{"citation":"Scottish Dental Clinical Effectiveness Programme: Management of Dental Patients Taking Anticoagulants or Antiplatelet Drugs","edition":"Second edition","section":"Introduction: About this guidance","url":"https://companion.sdcep.org.uk/management-of-dental-patients-taking-anticoagulants-or-antiplatelet-drugs/introduction/about-this-guidance/","checked_on":"2026-11-24"}],"note":"AI-assisted source preparation, NOT independent clinical approval. Existing draft unchanged. The medicine, indication, regimen, other drugs, bleeding history, patient conditions and procedure complexity are missing. The original generic red flags and case guidance do not distinguish anticoagulant classes or decision boundaries. Retain an information-gathering scenario; do not activate a patient-specific drug interruption or procedural plan. Candidate v0.2 requires further revision. Source metadata does not certify clinical truth, MCQ validity or Indian applicability."}}]'::jsonb) LOOP
    s := public._content_curriculum_snapshot(r->>'kind',(r->>'entity_id')::uuid);
    IF s IS NULL THEN RAISE EXCEPTION 'Expected draft is missing'; END IF;
    fp := encode(sha256(convert_to((s->'payload')::text,'UTF8')),'hex');
    IF fp IS DISTINCT FROM r->>'fingerprint' OR s->>'status' NOT IN ('draft','in_review') OR NOT EXISTS(
      SELECT 1 FROM public.subjects WHERE id=(s->>'subject_id')::uuid AND slug=r->>'subject_slug'
    ) THEN RAISE EXCEPTION 'Draft changed: inspect and prepare a fresh audit'; END IF;
    SELECT * INTO old FROM public.content_curriculum_evidence WHERE id=(r->>'id')::uuid;
    IF FOUND THEN
      IF old.entity_type IS DISTINCT FROM r->>'kind' OR old.entity_id IS DISTINCT FROM (r->>'entity_id')::uuid
        OR old.content_fingerprint IS DISTINCT FROM fp OR old.evidence IS DISTINCT FROM r->'evidence'
        OR old.version IS DISTINCT FROM (r->>'expected_version')::int+1 OR old.created_by IS NOT NULL
      THEN RAISE EXCEPTION 'Evidence retry id already belongs to another request'; END IF;
    ELSE
      SELECT coalesce(max(version),0) INTO v FROM public.content_curriculum_evidence
        WHERE entity_type=r->>'kind' AND entity_id=(r->>'entity_id')::uuid;
      IF v IS DISTINCT FROM (r->>'expected_version')::int THEN RAISE EXCEPTION 'Preparation version changed'; END IF;
      INSERT INTO public.content_curriculum_evidence(id,entity_type,entity_id,version,content_fingerprint,evidence,created_by)
        VALUES((r->>'id')::uuid,r->>'kind',(r->>'entity_id')::uuid,v+1,fp,r->'evidence',NULL);
    END IF;
  END LOOP;
END; $preparation$;
COMMIT;
